alter table public.traveling_tokens add column if not exists carrier_id uuid references auth.users(id) on delete set null;
create or replace function public.log_traveling_token_find(p_nfc_public_token uuid,p_box_code text) returns table(token_id uuid,token_code text,status text,box_code text) language plpgsql security definer set search_path='' as $$ declare v_token public.traveling_tokens%rowtype; v_box public.physical_treasure_boxes%rowtype; v_stop public.traveling_token_stops%rowtype; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select * into v_token from public.traveling_tokens where nfc_public_token=p_nfc_public_token for update; if v_token.id is null or v_token.status<>'in_circulation' then raise exception 'This token is not currently available to be found'; end if; select * into v_box from public.physical_treasure_boxes where upper(serial_code)=upper(trim(p_box_code)) limit 1; if v_box.id is null then raise exception 'We could not find that Treasure Box ID'; end if; if v_token.current_box_id is distinct from v_box.id then raise exception 'That is not the Treasure Box where this token is currently recorded'; end if; select * into v_stop from public.traveling_token_stops where traveling_token_id=v_token.id order by stop_number desc limit 1; update public.traveling_token_stops set departed_at=now(),departed_by=auth.uid() where id=v_stop.id and departed_at is null; update public.traveling_tokens set status='in_transit',carrier_id=auth.uid(),current_box_id=null,updated_at=now() where id=v_token.id; return query select v_token.id,v_token.token_code,'in_transit'::text,v_box.serial_code; end; $$;
create or replace function public.replant_traveling_token(p_nfc_public_token uuid,p_box_code text) returns table(token_id uuid,token_code text,status text,box_code text,stop_number integer,distance_miles numeric) language plpgsql security definer set search_path='' as $$ declare v_token public.traveling_tokens%rowtype; v_box public.physical_treasure_boxes%rowtype; v_prev public.traveling_token_stops%rowtype; v_distance numeric:=0; v_next integer; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select * into v_token from public.traveling_tokens where nfc_public_token=p_nfc_public_token for update; if v_token.id is null or v_token.status<>'in_transit' or v_token.carrier_id is distinct from auth.uid() then raise exception 'This token is not in your care'; end if; select * into v_box from public.physical_treasure_boxes where upper(serial_code)=upper(trim(p_box_code)) and cache_id is not null limit 1; if v_box.id is null then raise exception 'We could not find a set-up Treasure Box with that ID'; end if; select * into v_prev from public.traveling_token_stops where traveling_token_id=v_token.id order by stop_number desc limit 1; if v_prev.physical_box_id=v_box.id then raise exception 'Choose a different Treasure Box so this traveler can continue its journey'; end if; select coalesce(round((gis.st_distance(a1.search_center,a2.search_center)/1609.344)::numeric,2),0) into v_distance from public.physical_treasure_boxes b1 join public.cache_search_areas a1 on a1.cache_id=b1.cache_id join public.cache_search_areas a2 on a2.cache_id=v_box.cache_id where b1.id=v_prev.physical_box_id; v_next:=coalesce(v_prev.stop_number,0)+1; insert into public.traveling_token_stops(traveling_token_id,physical_box_id,stop_number,arrived_at,arrived_by,distance_from_previous_miles) values(v_token.id,v_box.id,v_next,now(),auth.uid(),v_distance); update public.traveling_tokens set status='in_circulation',carrier_id=null,current_box_id=v_box.id,updated_at=now() where id=v_token.id; return query select v_token.id,v_token.token_code,'in_circulation'::text,v_box.serial_code,v_next,v_distance; end; $$;
create or replace function public.get_carried_traveling_tokens() returns table(token_id uuid,nfc_public_token uuid,token_code text,name text,mission text,status text,picked_up_at timestamptz,from_box_code text,total_miles numeric,stop_count bigint) language sql stable security definer set search_path='' as $$ select t.id,t.nfc_public_token,t.token_code,t.name,t.mission,t.status,s.departed_at,b.serial_code,coalesce((select sum(x.distance_from_previous_miles) from public.traveling_token_stops x where x.traveling_token_id=t.id),0),coalesce((select count(*) from public.traveling_token_stops x where x.traveling_token_id=t.id),0) from public.traveling_tokens t left join public.traveling_token_stops s on s.traveling_token_id=t.id and s.stop_number=(select max(s2.stop_number) from public.traveling_token_stops s2 where s2.traveling_token_id=t.id) left join public.physical_treasure_boxes b on b.id=s.physical_box_id where t.carrier_id=auth.uid() and t.status='in_transit' order by s.departed_at desc; $$;
revoke all on function public.log_traveling_token_find(uuid,text) from public; grant execute on function public.log_traveling_token_find(uuid,text) to authenticated; revoke all on function public.replant_traveling_token(uuid,text) from public; grant execute on function public.replant_traveling_token(uuid,text) to authenticated; revoke all on function public.get_carried_traveling_tokens() from public; grant execute on function public.get_carried_traveling_tokens() to authenticated;